<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import transferReview from "./transferReview";

export default {
  name: "DistrictHRTransferRecommendationReview",
  mixins: [generalMixin, processQuestionnaire, transferReview],

  data() {
    return {
      url:
        "http://ihris.org/fhir/Questionnaire/district-hr-transfer-recommendation-review",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/review-hod-recommended-transfer-profile",

      stageConfig: {
        reviewerCode: "districthr",
        expectedStatus: "underdistricthrreview",
        label: "District HR",
        // Same pattern as hr-training-plan-review.vue's checkAccess(): look
        // up the District HR coverage entry for the *logged-in* user (via
        // the existing GET /site/general/getHR/:practitioner endpoint,
        // which derives district/facility from whichever practitioner id
        // is passed in), confirm the logged-in user is genuinely listed
        // among that entry's `practitioners`, then confirm the transferring
        // staff member's facility falls within that entry's `coverage`.
        checkAuthorized: async (ctx) => {
          try {
            const practitionerId = ctx.loggedInStaff?.practitioner;
            if (!practitionerId) return false;

            const res = await fetch(`/site/general/getHR/${practitionerId}`);
            if (!res.ok) return false;
            const hrList = await res.json();

            const matched = Array.isArray(hrList)
              ? hrList.find((h) =>
                  h.practitioners?.find((p) => p === practitionerId),
                )
              : null;
            if (!matched) return false;

            const coverage = Array.isArray(matched.coverage)
              ? matched.coverage
              : [];
            const staffFacilityId = ctx.currentPosition?.facilityId;
            if (!staffFacilityId) return false;

            return coverage.some(
              (f) => String(f.id) === String(staffFacilityId),
            );
          } catch (err) {
            console.error("District HR access check failed:", err);
            return false;
          }
        },
      },
    };
  },

  computed: {
    initials() {
      if (!this.staffName) return "?";
      return this.staffName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },
    currentStageLabel() {
      return (
        this.timeline.find((s) => s.code === this.currentStageCode)?.label ||
        "—"
      );
    },
    today() {
      return new Date().toISOString().substr(0, 10);
    },
  },
};
</script>

